const today = new Date().toISOString().split('T')[0];
const rows = $input.all().map(i => i.json);
const todayRows = rows.filter(r => r['Date']?.startsWith(today));
return [{ json: { responses: todayRows, count: todayRows.length, date: today } }];

parameters.text:
=Create a team standup digest from these responses.

Date: {{ $json.date }}
Responses: {{ JSON.stringify($json.responses) }}
Total submitted: {{ $json.count }}

Return JSON:
{
  "completed_yesterday": ["team-level summary of what was done"],
  "working_on_today": ["team-level summary of today's work"],
  "blockers": [{"person": "", "blocker": "", "needs_help_from": ""}],
  "who_submitted": [],
  "who_missed": [],
  "team_focus_today": "one sentence of team's main focus",
  "digest_message": "Slack message summarizing the standup"
}

=📋 *Standup Digest — {{ $now.toFormat('MMM dd') }}*

*Team Focus:* {{ $json.team_focus_today }}

{{ $json.digest_message }}

{{ $json.blockers.length > 0 ? '🚧 *Blockers:*\n' + $json.blockers.map(b=>`• ${b.person}: ${b.blocker}`).join('\n') : '✅ No blockers today' }}

*Submitted:* {{ $json.who_submitted.join(', ') }}
{{ $json.who_missed.length > 0 ? '*Missed:* ' + $json.who_missed.join(', ') : '' }}
